#include <algorithm>
#include <iostream>
#include <map>
#include <print>
#include <string>
#include <utility>

struct Node {
    int value;
    Node *left = nullptr;
    Node *right = nullptr;
};

Node *clone(const Node *n) {
    return n ? new Node{n->value, clone(n->left), clone(n->right)} : nullptr;
}

void destroy(Node *n) {
    if (n) {
        destroy(n->left);
        destroy(n->right);
        delete n;
    }
}

class Tree {
public:
    Tree() = default;
    Tree(const Tree &other) : root_(clone(other.root_)) {}
    Tree &operator=(const Tree &other) {
        Tree copy(other);
        std::swap(root_, copy.root_);
        return *this;
    }
    ~Tree() {
        destroy(root_);
    }

    void insert(int v) {
        Node **slot = &root_;
        while (*slot) {
            slot = v < (*slot)->value ? &(*slot)->left : &(*slot)->right;
        }
        *slot = new Node{v};
    }

    std::string text() const {
        std::string s;
        walk(root_, s);
        return s.empty() ? "пусто" : s;
    }

    int height() const {
        return height(root_);
    }

private:
    static void walk(const Node *n, std::string &s) {
        if (n) {
            walk(n->left, s);
            s += (s.empty() ? "" : " ") + std::to_string(n->value);
            walk(n->right, s);
        }
    }

    static int height(const Node *n) {
        return n ? 1 + std::max(height(n->left), height(n->right)) : 0;
    }

    Node *root_ = nullptr;
};

int main() {
    std::map<std::string, Tree> trees;
    std::string command, t;
    while (std::cin >> command >> t) {
        if (command == "insert") {
            int x;
            std::cin >> x;
            trees[t].insert(x);
        } else if (command == "copy") {
            std::string from;
            std::cin >> from;
            trees[t] = trees[from];
        } else if (command == "print") {
            std::println("{}: {}", t, trees[t].text());
        } else {
            std::println("{}: высота {}", t, trees[t].height());
        }
    }
    return 0;
}

