#include <iostream>
#include <map>
#include <print>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

struct Node {
    std::string name;
    std::vector<Node *> out;
};

class Graph {
public:
    Graph() = default;

    Graph(const Graph &other) {
        std::unordered_map<const Node *, Node *> twin;
        nodes_.reserve(other.nodes_.size());
        for (const Node *n : other.nodes_) {
            nodes_.push_back(new Node{n->name, {}});
            twin[n] = nodes_.back();
        }
        for (const Node *n : other.nodes_) {
            for (const Node *target : n->out) {
                twin.at(n)->out.push_back(twin.at(target));
            }
        }
    }

    Graph &operator=(const Graph &other) {
        Graph copy(other);
        std::swap(nodes_, copy.nodes_);
        return *this;
    }

    ~Graph() {
        for (Node *n : nodes_) {
            delete n;
        }
    }

    void add_node(const std::string &name) {
        nodes_.push_back(new Node{name, {}});
    }

    void add_edge(const std::string &a, const std::string &b) {
        find(a)->out.push_back(find(b));
    }

    void rename(const std::string &from, const std::string &to) {
        find(from)->name = to;
    }

    void print(const std::string &title) const {
        std::println("{}:", title);
        for (const Node *n : nodes_) {
            std::string targets;
            for (const Node *t : n->out) {
                targets += (targets.empty() ? "" : " ") + t->name;
            }
            std::println("{} → {}", n->name, targets.empty() ? "—" : targets);
        }
    }

private:
    Node *find(const std::string &name) const {
        for (Node *n : nodes_) {
            if (n->name == name) {
                return n;
            }
        }
        return nullptr;
    }

    std::vector<Node *> nodes_;
};

int main() {
    std::map<std::string, Graph> graphs;
    std::string command, g;
    while (std::cin >> command >> g) {
        if (command == "node") {
            std::string name;
            std::cin >> name;
            graphs[g].add_node(name);
        } else if (command == "edge") {
            std::string a, b;
            std::cin >> a >> b;
            graphs[g].add_edge(a, b);
        } else if (command == "copy") {
            std::string from;
            std::cin >> from;
            graphs[g] = graphs[from];
        } else if (command == "rename") {
            std::string a, b;
            std::cin >> a >> b;
            graphs[g].rename(a, b);
        } else {
            graphs[g].print(g);
        }
    }
    return 0;
}

